import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'data'
items={}
for id,name,kind,attack,speed,reach,cost,price in [('rust_sword','Wayfarer Sword','sword',12,.38,82,9,0),('dagger','Widow Dagger','dagger',8,.2,65,5,35),('axe','Executioner Axe','axe',23,.7,92,16,65),('staff','Cinder Staff','staff',18,.6,280,8,60),('bow','Yew Bow','bow',15,.48,360,7,50),('bellblade','Bellkeeper Blade','sword',28,.4,100,11,200)]:
 items[id]={'name':name,'slot':'weapon','kind':kind,'attack':attack,'speed':speed,'reach':reach,'cost':cost,'price':price,'rarity':'Rare' if id=='bellblade' else 'Common','description':'A relic carried through the dying kingdom.'}
for id,name,slot,defense,price in [('hood','Ash Hood','head',2,25),('mail','Pilgrim Mail','chest',5,55),('gloves','Hunter Gloves','gloves',2,25),('boots','Marsh Boots','boots',2,30),('charm','Silver Charm','accessory',3,45),('crown','Funeral Crown','head',6,120)]:items[id]={'name':name,'slot':slot,'defense':defense,'price':price,'rarity':'Uncommon','description':'Offers protection against the Veil.'}
for id,name,price,effect in [('potion','Healing Draught',12,'heal'),('ether','Moon Ether',15,'mana'),('tonic','Iron Tonic',14,'stamina'),('antidote','Bitter Antidote',8,'cleanse'),('ore','Grave Iron',10,''),('herb','Weeping Herb',6,''),('key','Crypt Sigil',0,''),('ember','Veil Ember',20,'')]:items[id]={'name':name,'slot':'','price':price,'effect':effect,'rarity':'Common','description':'Gathered from the ruins of Hollowmere.'}
(p/'items.json').write_text(json.dumps(items,indent=2))
npcs=[('mara','Mara','merchant','Keep your hands where I can see them. Crowns speak clearer than promises.'),('brann','Brann','smith','The bell broke. My anvil did not. Bring iron and I will make you dangerous.'),('sister','Sister Elowen','healer','Sit. Your wounds are honest, even if your memories are not.'),('tovin','Tovin','resident','Something wore my brother’s face in the woods. Please find his charm.'),('ilya','Captain Ilya','quest','The crypt gate needs a sigil. The forest sentinel carries it. End the bell’s silence.'),('osric','Osric','fanatic','The Veil is a mercy! Or perhaps... I need it to be.'),('vesper','Vesper','wanderer','You have been here before. Ask the shrine what you chose to forget.'),('nell','Nell','innkeeper','Beds cost coin. Rumors cost courage. The hounds fear fire.')]
(p/'npcs.json').write_text(json.dumps({x[0]:{'name':x[1],'role':x[2],'line':x[3]} for x in npcs},indent=2))
enemies={}
for id,hp,attack,speed,xp,behavior in [('wanderer',38,6,45,15,'melee'),('hound',28,5,100,16,'lunge'),('cultist',32,7,50,20,'ranged'),('guardian',70,11,32,32,'slam'),('wraith',45,6,65,24,'curse'),('knight',55,9,68,30,'counter'),('boss',390,12,40,200,'boss')]:enemies[id]={'hp':hp,'attack':attack,'speed':speed,'xp':xp,'behavior':behavior}
(p/'enemies.json').write_text(json.dumps(enemies,indent=2))
quests={'bell':{'name':'The Silent Bell','text':'Speak to Ilya. Defeat the forest sentinel for the sigil, enter the crypt, silence the Bellkeeper, then visit the shrine.','reward':100},'herbs':{'name':'A Gentle Mercy','text':'Bring three Weeping Herbs to Sister Elowen.','reward':35},'charm':{'name':'A Brother’s Shadow','text':'Recover the Silver Charm from a forest chest. Return it or keep it.','reward':40},'iron':{'name':'Iron Remembers','text':'Bring three Grave Iron to Brann.','reward':40},'elites':{'name':'Three Unquiet Souls','text':'Defeat the forest sentinel, the lost hound and the crypt knight.','reward':75}}
(p/'quests.json').write_text(json.dumps(quests,indent=2))
